const test = require('node:test');
const assert = require('node:assert');
const { slugify } = require('./slugify');

test('lowercases a title and joins its words with one dash', () => {
  assert.strictEqual(slugify('Hello, World!'), 'hello-world');
});

test('collapses runs of separators and trims dashes from both ends', () => {
  assert.strictEqual(slugify('  --A  b--'), 'a-b');
});

/**
 * Turn a title into a URL slug: lowercase, every run of characters outside
 * `a-z0-9` collapsed to one dash, dashes trimmed from both ends.
 *
 * @param {string} title
 * @returns {string}
 */
function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

module.exports = { slugify };

/**
 * Turn a title into a URL slug: lowercase, every run of characters outside
 * `a-z0-9` collapsed to one dash, dashes trimmed from both ends.
 *
 * @param {string} title
 * @returns {string}
 */
function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

